      "arFull": "بَرَآءَةٌ مِّنَ اللّٰهِ وَرَسُوْلِهٖۤ اِلَی الَّذِیْنَ عٰهَدْتُّمْ مِّنَ الْمُشْرِكِیْنَ ۟ؕ",
      "ur": "اللہ اوراس کے رسول کی جانب سے بیزاری کا اعلان ہے[1] ۔ ان مشرکوں کے بارے میں جن سے تم نے عہد وپیمان کیا تھا۔",
      "en": "[This is a declaration of] disassociation, from Allāh and His Messenger, to those with whom you had made a treaty among the polytheists.[461]",
      "footnotesUr": "[1] فتح مکہ کے بعد 9 ہجری میں رسول اللہ (صلى الله عليه وسلم) نے حضرت ابو بکر صدیق (رضي الله عنه)، حضرت علی (رضي الله عنه) اور دیگر صحابہ کو قرآن کریم کی یہ آیت اور یہ احکام دے کر بھیجا تاکہ وہ مکے میں ان کا عام اعلان کردیں۔ انہوں نے آپ (صلى الله عليه وسلم) کے فرمان کے مطابق اعلان کر دیا کہ کوئی شخص بیت اللہ کا عریاں طواف نہیں کرے گا، بلکہ آئندہ سال سے کسی مشرک کو بیت اللہ کے حج کی ہی اجازت نہیں ہوگی (صحيح بخاري كتاب الصلاة، باب ما يستر من العورة، مسلم كتاب الحج باب لا يحج البيت مشرك)",
