      "arFull": "لَا یَرْقُبُوْنَ فِیْ مُؤْمِنٍ اِلًّا وَّلَا ذِمَّةً ؕ وَاُولٰٓىِٕكَ هُمُ الْمُعْتَدُوْنَ ۟",
