      "arFull": "مَا كَانَ لِلْمُشْرِكِیْنَ اَنْ یَّعْمُرُوْا مَسٰجِدَ اللّٰهِ شٰهِدِیْنَ عَلٰۤی اَنْفُسِهِمْ بِالْكُفْرِ ؕ اُولٰٓىِٕكَ حَبِطَتْ اَعْمَالُهُمْ ۖۚ وَفِی النَّارِ هُمْ خٰلِدُوْنَ ۟",
      "ur": "ﻻئق نہیں کہ مشرک اللہ تعالیٰ کی مسجدوں کو آباد کریں۔ درآں حالیکہ وه خود اپنے کفر کے آپ ہی گواه ہیں[1] ، ان کے اعمال غارت واکارت ہیں، اور وه دائمی طور پر جہنمی ہیں۔[2]",
      "en": "It is not for the polytheists to maintain the mosques of Allāh [while] witnessing against themselves with disbelief. [For] those, their deeds have become worthless, and in the Fire they will abide eternally.",
      "footnotesUr": "[1] مَسَاجِدَ اللهِ سے مراد مسجد حرام ہے جمع کا لفظ اس لئے استعمال کیا گیا کہ یہ تمام مساجد کا قبلہ و مرکز ہے یا عربوں میں واحد کے لئے بھی جمع کا استعمال جائز ہے۔ مطلب یہ ہے کہ اللہ کے گھر (یعنی مسجد حرام) کو تعمیر یا آباد کرنا، یہ ایمان والوں کا کام ہے نہ کہ ان کا جو کفر و شرک کا ارتکاب اور اس کا اعتراف کرتے ہیں۔ جیسے وہ تلبیہ میں کہا کرتے تھے: «لَبَّيْكَ لا شَرِيكَ لَكَ، إِلا شَرِيكًا هُوَ لَكَ ، تَمْلِكُهُ وَمَا مَلَكَ» ( صحيح مسلم- باب التلبية) یا اس سے مراد وہ اعتراف ہے جو ہر مذہب والا کرتا ہے کہ میں یہودی، نصرانی، صابی یا مشرک ہوں۔(فتح القدیر)\n[2] یعنی ان کے وہ عمل جو بظاہر نیک لگتے ہیں، جیسے طواف و عمرہ اور حاجیوں کی خدمت وغیرہ۔ کیونکہ ایمان کے بغیر یہ اعمال ایسے درخت کی طرح ہیں جو بےثمر ہیں یا ان پھولوں کی طرح ہیں جن میں خو شبو نہیں ہے۔",
