      "arFull": "وَقَالَتِ الْیَهُوْدُ عُزَیْرُ بْنُ اللّٰهِ وَقَالَتِ النَّصٰرَی الْمَسِیْحُ ابْنُ اللّٰهِ ؕ ذٰلِكَ قَوْلُهُمْ بِاَفْوَاهِهِمْ ۚ یُضَاهِـُٔوْنَ قَوْلَ الَّذِیْنَ كَفَرُوْا مِنْ قَبْلُ ؕ قٰتَلَهُمُ اللّٰهُ ؗۚ اَنّٰی یُؤْفَكُوْنَ ۟",
