      "arFull": "هُوَ الَّذِیْۤ اَرْسَلَ رَسُوْلَهٗ بِالْهُدٰی وَدِیْنِ الْحَقِّ لِیُظْهِرَهٗ عَلَی الدِّیْنِ كُلِّهٖ ۙ وَلَوْ كَرِهَ الْمُشْرِكُوْنَ ۟",
      "ur": "اسی نے اپنے رسول کو ہدایت اور سچے دین کے ساتھ بھیجا ہے کہ اسے اور تمام مذہبوں پر غالب کر دے[1] اگر چہ مشرک برا مانیں",
      "en": "It is He who has sent His Messenger with guidance and the religion of truth to manifest it over all religion, although they who associate others with Allāh dislike it.",
