      "arFull": "یَّوْمَ یُحْمٰی عَلَیْهَا فِیْ نَارِ جَهَنَّمَ فَتُكْوٰی بِهَا جِبَاهُهُمْ وَجُنُوْبُهُمْ وَظُهُوْرُهُمْ ؕ هٰذَا مَا كَنَزْتُمْ لِاَنْفُسِكُمْ فَذُوْقُوْا مَا كُنْتُمْ تَكْنِزُوْنَ ۟",
