      "en": "Had it been a near [i.e., easy] gain and a moderate trip, they [i.e., the hypocrites] would have followed you, but distant to them was the journey. And they will swear by Allāh,[481] \"If we were able, we would have gone forth with you,\" destroying themselves [through false oaths], and Allāh knows that indeed they are liars.",
      "footnotesUr": "[1] یہاں سے ان لوگوں کا بیان شروع ہو رہا ہے جنہوں نے عذر اور معذرت کر کے نبی (صلى الله عليه وسلم) سے اجازت لے لی تھی دراں حالانکہ ان کے پاس حقیقت میں کوئی عذر نہیں تھا۔ ”عَرَضٌ“ سے مراد جو دنیاوی منافع سامنے آئیں مطلب ہے مال غنیمت۔\n[2] یعنی آپ (صلى الله عليه وسلم) کے ساتھ شریک جہاد ہوتے۔ لیکن سفر کی دوری نے انہیں حیلے تراشنے پر مجبور کر دیا۔\n[3] یعنی جھوٹی قسمیں کھا کر۔ کیونکہ جھوٹی قسم کھانا گناہ کبیرہ ہے۔",
