      "number": 46,
      "arFull": "وَلَوْ اَرَادُوا الْخُرُوْجَ لَاَعَدُّوْا لَهٗ عُدَّةً وَّلٰكِنْ كَرِهَ اللّٰهُ انْۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِیْلَ اقْعُدُوْا مَعَ الْقٰعِدِیْنَ ۟",
      "ur": "اگر ان کا اراده جہاد کے لئے نکلنے کا ہوتا تو وه اس سفر کے لئے سامان کی تیاری کر رکھتے[1] لیکن اللہ کو ان کا اٹھنا پسند ہی نہ تھا اس لئے انہیں حرکت سے ہی روک دیا[2] اور کہہ دیا گیا کہ تم بیٹھنے والوں کے ساتھ بیٹھے ہی رہو۔[3]",
      "en": "And if they had intended to go forth, they would have prepared for it [some] preparation. But Allāh disliked their being sent, so He kept them back, and they were told, \"Remain [behind] with those who remain.\"[482]",
      "footnotesUr": "[1] یہ انہیں منافقوں کے بارے میں کہا جا رہا ہے جنہوں نے جھوٹ بول کر اجازت حاصل کی تھی کہ اگر وہ جہاد میں جانے کا ارادہ رکھتے تو یقینا اس کے لئے تیاری کرتے۔\n[2] ”فَثَبَّطَهُمْ“ کے معنی ہیں انکو روک دیا، پیچھے رہنا ان کے لئے پسندیدہ بنا دیا گیا، پس وہ سست ہوگئے اور مسلمانوں کے ساتھ نہیں نکلے مطلب یہ ہے کہ اللہ کے علم میں ان کی شرارتیں اور سازشیں تھیں، اس لئے اللہ کی تقدیری مشیت یہی تھی کہ وہ نہ جائیں۔\n[3] یہ یا تو اسی مشیت الٰہی کی تعبیر ہے جو تقدیرا لکھی ہوئی تھی یا بطور ناراضگی اور غضب کے رسول اللہ (صلى الله عليه وسلم) کی طرف سے کہا گیا ہے کہ اچھا ٹھیک ہے تم عورتوں، بچوں، بیماروں اور بوڑھوں کی صف میں شامل ہو کر ان کی طرح گھروں میں بیٹھے رہو۔",
      "footnotesEn": "[482] i.e., the women and children.",
