      "number": 50,
      "arFull": "اِنْ تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ ۚ وَاِنْ تُصِبْكَ مُصِیْبَةٌ یَّقُوْلُوْا قَدْ اَخَذْنَاۤ اَمْرَنَا مِنْ قَبْلُ وَیَتَوَلَّوْا وَّهُمْ فَرِحُوْنَ ۟",
      "ur": "آپ کو اگر کوئی بھلائی مل جائے تو انہیں برا لگتا ہے اور کوئی برائی پہنچ جائے تو یہ کہتے ہیں ہم نے تو اپنا معاملہ پہلے سے ہی درست کر لیا تھا، پھر تو بڑے ہی اتراتے ہوئے لوٹتے ہیں۔[1]",
      "en": "If good befalls you, it distresses them; but if disaster strikes you, they say, \"We took our matter [in hand] before,\"[485] and turn away while they are rejoicing.",
      "footnotesUr": "[1] سیاق کلام کے اعتبار سے حَسَنةٌ، سے یہاں کامیابی اور غنیمت اور سَيّئَةٌ سے ناکامی، شکست اور اسی قسم کے نقصانات جو جنگ میں متوقع ہوتے ہیں مراد ہیں۔ اس میں ان کے خبث باطنی کا اظہار ہے جو منافقین کے دلوں میں تھا اس لئے کہ مصیبت پر خوش ہونا اور بھلائی حاصل ہونے پر رنج اور تکلیف محسوس کرنا، غایت عداوت کی دلیل ہے۔",
      "footnotesEn": "[485] The hypocrites claim to have protected themselves by remaining behind.",
