      "arFull": "وَعَدَ اللّٰهُ الْمُؤْمِنِیْنَ وَالْمُؤْمِنٰتِ جَنّٰتٍ تَجْرِیْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِیْنَ فِیْهَا وَمَسٰكِنَ طَیِّبَةً فِیْ جَنّٰتِ عَدْنٍ ؕ وَرِضْوَانٌ مِّنَ اللّٰهِ اَكْبَرُ ؕ ذٰلِكَ هُوَ الْفَوْزُ الْعَظِیْمُ ۟۠",
      "ur": "ان ایمان دار مردوں اور عورتوں سے اللہ نے ان جنتوں کا وعده فرمایا ہے جن کے نیچے نہریں لہریں لے رہی ہیں جہاں وه ہمیشہ ہمیشہ رہنے والے ہیں اور ان صاف ستھرے پاکیزه محلات[1] کا جو ان ہمیشگی والی جنتوں میں ہیں، اور اللہ کی رضامندی سب سے بڑی چیز ہے[2]، یہی زبردست کامیابی ہے۔",
      "en": "Allāh has promised the believing men and believing women gardens beneath which rivers flow, wherein they abide eternally, and pleasant dwellings in gardens of perpetual residence; but approval from Allāh is greater. It is that which is the great attainment.",
