      "ur": "آپ کو ان کے مال واوﻻد کچھ بھی بھلے نہ لگیں! اللہ کی چاہت یہی ہے کہ انہیں ان چیزوں سے دنیوی سزا دے اور یہ اپنی جانیں نکلنے تک کافر ہی رہیں۔",
