      "number": 97,
      "arFull": "اَلْاَعْرَابُ اَشَدُّ كُفْرًا وَّنِفَاقًا وَّاَجْدَرُ اَلَّا یَعْلَمُوْا حُدُوْدَ مَاۤ اَنْزَلَ اللّٰهُ عَلٰی رَسُوْلِهٖ ؕ وَاللّٰهُ عَلِیْمٌ حَكِیْمٌ ۟",
      "ur": "دیہاتی لوگ کفر اور نفاق میں بہت ہی سخت ہیں[1] اور ان کو ایسا ہونا ہی چاہئے کہ ان کو ان احکام کا علم نہ ہو جو اللہ تعالیٰ نے اپنے رسول پر نازل فرمائے[2] ہیں اور اللہ بڑا علم واﻻ بڑی حکمت واﻻ ہے۔",
      "en": "The bedouins are stronger in disbelief and hypocrisy and more likely not to know the limits of what [laws] Allāh has revealed to His Messenger. And Allāh is Knowing and Wise.",
      "footnotesUr": "[1] مذکورہ آیات میں ان منافقین کا تذکرہ تھا جو مدینہ شہر میں رہائش پذیر تھے۔ اور کچھ منافقین وہ بھی تھے جو بادیہ نشین یعنی مدینہ کے باہر دیہاتوں میں رہتے تھے، دیہات کے ان باشندوں کو اعراب کہا جاتا ہے جو اعرابی کی جمع ہے شہریوں کے اخلاق و کردار میں درشتی اور کھردراپن زیادہ پایا جاتا ہے اس طرح ان میں جو کافر اور منافق تھے وہ کفر و نفاق میں بھی شہریوں سے زیادہ سخت اور احکام شریعت سے زیادہ بےخبر تھے اس آیت میں انہی کا تذکرہ اور انکے اسی کردار کی وضاحت ہے۔ بعض احادیث سے بھی ان کے کردار پر روشنی پڑتی ہے۔ مثلًا ایک موقع پر کچھ اعرابی رسول اللہ (صلى الله عليه وسلم) کی خدمت میں حاضر ہوئے اور انہوں نے پوچھا «اَتُقَبْلُوْنَ صِبْیَانکُمْ»، ”کیا تم اپنے بچے کو بوسہ دیتے ہو؟“، صحابہ (رضي الله عنهم) نے عرض کیا ”ہاں“ انہوں نے کہا ”واللہ! ہم تو بوسہ نہیں دیتے“ رسول اللہ (صلى الله عليه وسلم) نے سن کر فرمایا ”اگر اللہ نے تمہارے دلوں میں سے رحم و شفقت کا جذبہ نکال دیا ہے تو میرا اس میں کیا اختیار ہے؟“۔ (صحیح بخاری کتاب الأدب، باب رحمة الولد وتقبیله ومعانقته۔ صحیح مسلم، کتاب الفضائل، باب رحمته صلى الله عليه وسلم الصبیان والعیال)\n[2] اس کی وجہ یہ ہے کہ چوں کہ وہ شہر سے دور رہتے ہیں اور اللہ اور رسول (صلى الله عليه وسلم) کی باتیں سننے کا اتفاق ان کو نہیں ہوتا۔",
