      "arFull": "وَمِنَ الْاَعْرَابِ مَنْ یَّتَّخِذُ مَا یُنْفِقُ مَغْرَمًا وَّیَتَرَبَّصُ بِكُمُ الدَّوَآىِٕرَ ؕ عَلَیْهِمْ دَآىِٕرَةُ السَّوْءِ ؕ وَاللّٰهُ سَمِیْعٌ عَلِیْمٌ ۟",
      "ur": "اور ان دیہاتیوں میں سے بعض[1] ایسے ہیں کہ جو کچھ خرچ کرتے ہیں اس کو جرمانہ سمجھتے ہیں[2] اور تم مسلمانوں کے واسطے برے وقت کے منتظر رہتے ہیں[3]، برا وقت ان ہی پر پڑنے واﻻ ہے[4] اور اللہ سننے واﻻ جاننے واﻻ ہے۔",
