      "arFull": "وَمِنَ الْاَعْرَابِ مَنْ یُّؤْمِنُ بِاللّٰهِ وَالْیَوْمِ الْاٰخِرِ وَیَتَّخِذُ مَا یُنْفِقُ قُرُبٰتٍ عِنْدَ اللّٰهِ وَصَلَوٰتِ الرَّسُوْلِ ؕ اَلَاۤ اِنَّهَا قُرْبَةٌ لَّهُمْ ؕ سَیُدْخِلُهُمُ اللّٰهُ فِیْ رَحْمَتِهٖ ؕ اِنَّ اللّٰهَ غَفُوْرٌ رَّحِیْمٌ ۟۠",
      "ur": "اور بعض اہل دیہات میں ایسے بھی ہیں جو اللہ تعالیٰ پر اور قیامت کے دن پر ایمان رکھتے ہیں اور جو کچھ خرچ کرتے ہیں اس کو عنداللہ قرب حاصل ہونے کا ذریعہ اور رسول کی دعا کا ذریعہ بناتے ہیں[1] ، یاد رکھو کہ ان کا یہ خرچ کرنا بیشک ان کے لیے موجب قربت ہے، ان کو اللہ تعالیٰ ضرور اپنی رحمت میں داخل کرے گا[2]۔ اللہ تعالیٰ بڑی مغفرت واﻻ بڑی رحمت واﻻ ہے۔",
      "en": "But among the bedouins are some who believe in Allāh and the Last Day and consider what they spend as means of nearness to Allāh and of [obtaining] invocations of the Messenger. Unquestionably, it is a means of nearness for them. Allāh will admit them to His mercy. Indeed, Allāh is Forgiving and Merciful.",
      "footnotesUr": "[1] یہ اعراب کی دوسری قسم ہے جن کو اللہ نے شہر سے دور رہنے کے باوجود، اللہ اور یوم آخرت پر ایمان لانے کی توفیق عطا فرمائی۔ اور اس ایمان کی بدولت ان سے وہ جہالت بھی دور فرما دی جو بددینیت کی وجہ سے اہل بادیہ میں عام طور پر ہوتی ہے۔ چنانچہ وہ اللہ کی راہ میں خرچ کردہ مال کو جرمانہ سمجھنے کی بجائے۔ اللہ کے قرب کا اور رسول (صلى الله عليه وسلم) کی دعائیں لینے کا ذریعہ سمجھتے ہیں۔ یہ اشارہ ہے رسول اللہ (صلى الله عليه وسلم) کے اس طرز عمل کی طرف، جو صدقہ دینے والوں کے بارے میں آپ صلی اللہ علیہ وسلم کا تھا۔ یعنی آپ ان کے حق میں دعائے خیر فرماتے۔ جس طرح حدیث میں آتا ہے کہ ایک صدقہ لانے والے کے لئے آپ(صلى الله عليه وسلم) نے دعا فرمائی ”اللَّہُمَّ صَلِّ عَلَی آلِ اَبِیْ اَوْفٰی“ (صحیح بخاری نمبر 4166 ، صحیح مسلم نمبر 756) ”اے اللہ! ابو اوفی کی آل پر رحمت نازل فرما“\n[2] یہ خوشخبری ہے کہ اللہ کا قرب انہیں حاصل ہے اور اللہ کی رحمت کے وہ مستحق ہیں۔",
      "footnotesEn": null,
