      "number": 106,
      "arFull": "وَاٰخَرُوْنَ مُرْجَوْنَ لِاَمْرِ اللّٰهِ اِمَّا یُعَذِّبُهُمْ وَاِمَّا یَتُوْبُ عَلَیْهِمْ ؕ وَاللّٰهُ عَلِیْمٌ حَكِیْمٌ ۟",
      "ur": "اور کچھ اور لوگ ہیں جن کا معاملہ اللہ کے حکم آنے تک ملتوی ہے[1] ان کو سزا دے گا[2] یا ان کی توبہ قبول کرلے گا[3]، اور اللہ خوب جاننے واﻻ ہے بڑا حکمت واﻻ ہے۔",
      "en": "And [there are] others deferred until the command of Allāh - whether He will punish them or whether He will forgive them. And Allāh is Knowing and Wise.",
