      "number": 126,
      "arFull": "اَوَلَا یَرَوْنَ اَنَّهُمْ یُفْتَنُوْنَ فِیْ كُلِّ عَامٍ مَّرَّةً اَوْ مَرَّتَیْنِ ثُمَّ لَا یَتُوْبُوْنَ وَلَا هُمْ یَذَّكَّرُوْنَ ۟",
